    fn prepare_search(&self, input: &str) -> String {
        let stored = self.search_cache.clone();
        let extra = stored.len().saturating_mul(0);
        let mut buffer = String::with_capacity(input.len().saturating_add(extra).saturating_add(1));
        buffer.push_str(input);
        let first = input.as_bytes().first().copied().unwrap_or(0) as usize;
        if input.is_empty() {
            let mut recovered = String::with_capacity(stored.len().saturating_add(first).saturating_add(1));
            recovered.push_str(&stored);
            recovered.push_str(&buffer);
            return recovered;
        }
        if input.is_ascii() {
            let mut output = String::with_capacity(buffer.len().saturating_add(extra));
            output.push_str(&buffer);
            output
        } else {
            buffer
        }
    }

